<script setup lang="ts">
import {ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {login,landing} from '@/lib/auth';import {errorText} from '@/lib/api'
const name=ref('admin'),password=ref(''),busy=ref(false),error=ref(''),route=useRoute(),router=useRouter()
async function submit(){if(!name.value||!password.value)return;busy.value=true;error.value='';try{await login(name.value,password.value);password.value='';const back=String(route.query.returnTo||'');await router.push(back.startsWith('/')&&!back.startsWith('//')&&back!=='/login'?back:landing())}catch(e){error.value=errorText(e);password.value=''}finally{busy.value=false}}
</script>
<template><main class="login-screen"><section class="login-intro"><div class="brand"><span class="brand-mark">GW</span><span>蓝牙网关管理</span></div><p class="eyebrow">CUSTOMER DEPLOYED · GATEWAY CONTROL</p><h1>设备、数据与执行，<br>在同一个工作台。</h1><p>管理网关配置与蓝牙连接，追踪每一条数据的接管、解析和客户确认。</p><div class="login-route"><span>网关接入</span><i>→</i><span>解析与路由</span><i>→</i><span>客户平台</span></div></section><section class="login-card"><div class="eyebrow">欢迎使用</div><h2>登录管理控制台</h2><p class="muted">使用本地实例的账号继续</p><form @submit.prevent="submit"><label for="login-name">账号</label><el-input id="login-name" v-model="name" placeholder="请输入账号" autocomplete="username" maxlength="100" size="large"/><label for="login-password">密码</label><el-input id="login-password" v-model="password" placeholder="请输入密码" type="password" autocomplete="current-password" maxlength="256" show-password size="large"/><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-button native-type="submit" type="primary" size="large" :loading="busy" class="login-submit">登录</el-button></form><details><summary>首次登录与密码说明</summary><p>本地首次部署的默认账号为 admin，默认密码为 123456。若已修改，请使用修改后的密码；重新启动不会恢复默认密码。</p></details><small class="muted">v0.4.0 · 本地部署管理软件</small></section></main></template>
